/** Query parameters for `listFollowing` (/api/v1/profiles/{handle}/following). */
export interface ListFollowingQuery {
  /** Opaque `nextCursor` from a previous response, and the preferred way to page: there is no limit on how far a cursor chain goes. Send it back with the same query, feed and options. Never decode a cursor, edit it, or reuse it across feeds. A cursor takes precedence over `page`. */
  readonly cursor?: string
  /** Ordinal page, used only when no `cursor` is supplied. Values above 10 are clamped. Numbered paging walks every preceding upstream page, so it is slower than a cursor. */
  readonly page?: number
  /** Maximum results in the page. Values above 100 are clamped to 100. A bounded upstream walk returns at most `limit`; when the cut falls inside an upstream page the `nextCursor` carries an offset (`…@15`), so nothing is lost or repeated. Searches served by own accounts (`photos`, `videos`, `users`, or a fallback) answer at most 20 per request and report that in `limit`. */
  readonly limit?: number
  /** Return the expanded representation: metrics, timestamps and profile counts instead of the compact default. */
  readonly full?: boolean
  /** Bypass the application cache and fetch from the upstream provider. Charged against the live-lookup quota. */
  readonly nocache?: boolean
}

/** Query parameters for `searchPosts` (/api/v1/search). */
export interface SearchPostsQuery {
  /** Search terms. X search operators such as `from:`, `since:` and `filter:` are passed through. */
  readonly q: string
  /** Which search feed to read. `media` is an alias for `photos`. Unrecognised values fall back to `latest`. `photos`, `videos` and `users` need a configured live provider and answer 503 when none is available. */
  readonly feed?: 'latest' | 'top' | 'photos' | 'videos' | 'users' | 'media'
  /** Oldest post to match. Applied upstream as X's `since_time:` operator, so it works on every provider. */
  readonly since?: string
  /** Newest post to match. Applied upstream as X's `until_time:` operator. */
  readonly until?: string
  /** Opaque `nextCursor` from a previous response, and the preferred way to page: there is no limit on how far a cursor chain goes. Send it back with the same query, feed and options. Never decode a cursor, edit it, or reuse it across feeds. A cursor takes precedence over `page`. */
  readonly cursor?: string
  /** Ordinal page, used only when no `cursor` is supplied. Values above 10 are clamped. Numbered paging walks every preceding upstream page, so it is slower than a cursor. */
  readonly page?: number
  /** Maximum results in the page. Values above 100 are clamped to 100. A bounded upstream walk returns at most `limit`; when the cut falls inside an upstream page the `nextCursor` carries an offset (`…@15`), so nothing is lost or repeated. Searches served by own accounts (`photos`, `videos`, `users`, or a fallback) answer at most 20 per request and report that in `limit`. */
  readonly limit?: number
  /** Return the expanded representation: metrics, timestamps and profile counts instead of the compact default. */
  readonly full?: boolean
  /** Bypass the application cache and fetch from the upstream provider. Charged against the live-lookup quota. */
  readonly nocache?: boolean
  /** Reject degraded web snippets with 503 instead of treating them as a mention timeline. */
  readonly requireLive?: boolean
}

/** Query parameters for `getOEmbed` (/api/v1/oembed). */
export interface GetOEmbedQuery {
  /** Status permalink the embed describes. The handle and id are read back out of it. */
  readonly url?: string
  /** Text rendered as `author_name`; x.md puts the social-proof line here. */
  readonly text?: string
  /** Fallback handle when `url` is absent or is not a status permalink. */
  readonly author?: string
  /** Fallback numeric status id when `url` is absent or is not a status permalink. */
  readonly status?: string
  /** When present, `provider_name` takes this value and `type` becomes `rich` instead of `link`. */
  readonly provider?: string
}

